@startuml

class Museum {
  + Name : string
}

class Location {
  + Name : string
}

class Exhibition {
  + OpeningDate : date
}

class Employee {
  + Name : string
}

class ExhibitionItem {
  + Description : string
}

class Piece {
  + Description : string
}

class Collector {
  + Name : string
}

Museum "1" *-- "0..*" Location
Location "1" -- "0..*" Exhibition
Exhibition "0..*" -- "1" Employee : coordinator
Employee "0..1" -- "0..1" Employee : coach
Exhibition "1" *-- "1..*" ExhibitionItem
ExhibitionItem "1" -- "0..*" Piece
Piece "0..*" -- "1" Collector

@enduml

